svg.script:
(function () {
  var NS = "http://www.w3.org/2000/svg", svg = document.documentElement;
  var $ = function (id) { return document.getElementById(id); };
  // Déviation de l'OD sous le cache, en px dans l'image (sujet vu de face : la tempe de l'OD est à GAUCHE de l'image)
  var PHORIES = {
    exo:   { dx: -18, dy: 0,   nom: "Exophorie",       mvt: "temporo-nasal (vers le nez)", court: "Exo" },
    eso:   { dx: 18,  dy: 0,   nom: "Ésophorie",       mvt: "naso-temporal (vers la tempe)", court: "Éso" },
    hyper: { dx: 0,   dy: -14, nom: "Hyperphorie D/G", mvt: "de haut en bas", court: "Hyper D/G" },
    hypo:  { dx: 0,   dy: 14,  nom: "Hypophorie D/G",  mvt: "de bas en haut", court: "Hypo D/G" }
  };
  var ORDRE = ["exo", "eso", "hyper", "hypo"];
  var actuelle = "exo", minuteurs = [], defi = null;

  function el(nom, attrs, parent, txt) {
    var e = document.createElementNS(NS, nom);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt) e.textContent = txt;
    if (parent) parent.appendChild(e);
    return e;
  }
  function bouton(parent, x, y, w, texte, couleur, action) {
    var g = el("g", { "class": "bt", role: "button" }, parent);
    var r = el("rect", { x: x, y: y, width: w, height: 28, rx: 14, fill: couleur, "fill-opacity": ".12", stroke: couleur, "stroke-opacity": ".55" }, g);
    el("text", { x: x + w / 2, y: y + 19, "text-anchor": "middle" }, g, texte);
    g.addEventListener("click", action);
    return { g: g, r: r };
  }
  function etapes(a, b) { $("etape1").textContent = a; $("etape2").textContent = b || ""; }
  function bilan(t) { $("bilantexte").textContent = t; }
  function plus(f, ms) { minuteurs.push(setTimeout(f, ms)); }
  function iris(dx, dy) { $("irisD").style.transform = "translate(" + dx + "px," + dy + "px)"; }
  function cache(dedans) { $("cache").style.transform = dedans ? "translate(0px,0px)" : "translate(-250px,0px)"; }

  // Puces pour choisir la phorie à observer
  var puces = {};
  ORDRE.forEach(function (k, i) {
    puces[k] = bouton($("puces"), 212 + i * 66, 8, 62, PHORIES[k].court.replace(" D/G", ""), "#9ec5ff", function () { defi = null; actuelle = k; jouer(); });
  });
  function marquerPuce() { ORDRE.forEach(function (k) { puces[k].r.setAttribute("fill-opacity", k === actuelle ? ".35" : ".12"); }); }

  function flecheMouvement(p) {
    // Mouvement au démasquage = sens opposé à la déviation sous le cache
    var d = p.dx !== 0 ? "M" + (150 + p.dx * 1.8) + " 208 H" + 150 : "M60 " + (150 + p.dy * 2.4) + " V150";
    $("flechep").setAttribute("d", d);
  }

  function jouer(fin) {
    minuteurs.forEach(clearTimeout); minuteurs = [];
    var p = PHORIES[actuelle];
    marquerPuce(); flecheMouvement(p);
    $("fleche").setAttribute("opacity", "0");
    $("cacherect").setAttribute("fill-opacity", defi ? "1" : ".72");
    iris(0, 0); cache(false);
    etapes("1. Les deux yeux fixent le test", "");
    bilan(defi ? "🎯 Défi " + (defi.n + 1) + "/3 : observe bien" : "Phorie étudiée : " + p.nom);
    plus(function () { cache(true); etapes("2. Masquage de l'OD", "L'OG ne bouge pas : pas de tropie"); }, 900);
    plus(function () { iris(p.dx, p.dy); etapes("3. Derrière le cache, l'OD dévie", defi ? "(cache opaque : on ne voit rien)" : "Il prend sa position passive"); }, 2100);
    plus(function () { cache(false); }, 3400);
    plus(function () {
      iris(0, 0); $("fleche").setAttribute("opacity", "1");
      if (defi) { etapes("4. Démasquage : l'OD reprend la fixation", "Quelle est la phorie ?"); montrerReponses(); }
      else { etapes("4. Démasquage : mouvement " + p.mvt.split(" (")[0], p.mvt.indexOf("(") > 0 ? p.mvt.slice(p.mvt.indexOf("(")) : ""); bilan("Mouvement au démasquage → " + p.nom); }
      if (fin) fin();
    }, 3900);
  }

  // ---------- Défi : 3 phories au hasard, cache opaque ----------
  function montrerReponses() {
    var z = $("reponses"); while (z.firstChild) z.removeChild(z.firstChild);
    $("bilan").setAttribute("visibility", "hidden"); z.setAttribute("visibility", "visible");
    ORDRE.forEach(function (k, i) {
      bouton(z, 12 + i * 115, 296, 108, PHORIES[k].court, "#d9b26f", function () { repondre(k); });
    });
  }
  function repondre(k) {
    if (!defi || defi.attente) return;
    var p = PHORIES[actuelle], ok = k === actuelle;
    if (ok) defi.score++;
    defi.attente = true;
    $("reponses").setAttribute("visibility", "hidden"); $("bilan").setAttribute("visibility", "visible");
    $("bilanfond").setAttribute("stroke", ok ? "#5fd08a" : "#ff8a7a");
    bilan((ok ? "✓ Oui : " : "✕ Non : ") + p.mvt.split(" (")[0] + " = " + p.nom);
    plus(function () {
      $("bilanfond").setAttribute("stroke", "#d9b26f");
      defi.n++; defi.attente = false;
      if (defi.n >= 3) { bilan("Défi terminé : " + defi.score + "/3 " + (defi.score === 3 ? "🎉" : "")); etapes("Rejoue le défi pour t'entraîner", ""); defi = null; return; }
      actuelle = defi.tirage[defi.n]; jouer();
    }, 2200);
  }
  $("bdefi").addEventListener("click", function () {
    var t = ORDRE.slice().sort(function () { return Math.random() - .5; });
    defi = { n: 0, score: 0, tirage: t, attente: false };
    actuelle = t[0]; ["erreur", "errfleche", "errog"].forEach(function (i) { $(i).setAttribute("visibility", "hidden"); }); jouer();
  });
  $("rejouer").addEventListener("click", function () { defi = null; $("reponses").setAttribute("visibility", "hidden"); $("bilan").setAttribute("visibility", "visible"); jouer(); });

  // ---------- Réponse fausse de l'élève (numéros = position dans q.choix de questions-U5.js) ----------
  var ERREURS = {
    1: { val: "Ésophorie", quoi: "errfleche", pourquoi: "→ Une ésophorie : l'œil reviendrait vers la tempe." },
    2: { val: "Exotropie", quoi: "errog", pourquoi: "→ Une tropie se voit au masquage : l'OG bougerait." },
    3: { val: "Ésotropie", quoi: "errog", pourquoi: "→ Une tropie se voit au masquage : l'OG bougerait." }
  };
  var m = /faux=(\d)/.exec(location.hash), err = m && ERREURS[m[1]];
  if (err) svg.setAttribute("viewBox", "0 0 480 450");   // tout de suite : la page lit la taille au chargement
  jouer(function () {
    if (!err) return;
    $("errval").textContent = err.val;
    $("errpourquoi").textContent = err.pourquoi;
    $(err.quoi).setAttribute("visibility", "visible");
    $("erreur").setAttribute("visibility", "visible");
  });
})();
